// BUG 1: Custom object overrides equals() but misses hashCode()
    static class SecurityToken implements Comparable<SecurityToken> {
        String userId;
        int accessLevel;

        public SecurityToken(String userId, int accessLevel) {
            this.userId = userId;
            this.accessLevel = accessLevel;
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (o == null || getClass() != o.getClass()) return false;
            SecurityToken token = (SecurityToken) o;
            return accessLevel == token.accessLevel && Objects.equals(userId, token.userId);
        }



        @Override
        public int compareTo(SecurityToken other) {
            return this.userId.compareTo(other.userId);
        }

        @Override
        public String toString() {
            return userId + ":" + accessLevel;
        }
    }
